import geojson from "./model/geo.json";
const categories = [
    ["Hiking", /hik/i],
    ["Camping", /camp/i],
    ["Paddling", /kayak|boat/i],
    ["Fishing", /fish/i],
    ["Biking", /bik/i],
    ["Picnicking", /picni/i],
    ["Winter sports", /ski|snow/i],
    ["Sightseeing", /view|museum|shopping/i],
];
export const places = geojson.features.map((feature) => ({
    id: feature.id,
    name: feature.properties["Park Name"],
    description: feature.properties.Description,
    activities: categories
        .filter(([, expression]) => expression.test(feature.properties.Activities || ""))
        .map(([label]) => label),
    coordinates: [feature.geometry.coordinates[0], feature.geometry.coordinates[1]],
}));
export const activityOptions = categories.map(([label]) => label);
export function filterPlaces(data, query, activity) {
    const term = query.trim().toLocaleLowerCase();
    return data.filter((place) => (!activity || place.activities.includes(activity)) &&
        `${place.name} ${place.description} ${place.activities.join(" ")}`.toLocaleLowerCase().includes(term));
}
export function estimateMinutes(analysis, paceKmh) {
    if (!Number.isFinite(paceKmh) || paceKmh <= 0)
        throw new Error("Walking pace must be positive.");
    const climb = analysis.elevationPairs === analysis.totalPairs ? analysis.ascentM / 600 : 0;
    return Math.round((analysis.distanceM / 1000 / paceKmh + climb) * 60);
}
export const formatDistance = (meters) => `${(meters / 1000).toFixed(2)} km`;
export const formatDuration = (minutes) => minutes < 60 ? `${minutes} min` : `${Math.floor(minutes / 60)} h ${minutes % 60} min`;
